const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/error-counting-deep.jsonl';
// pairs come from a JSON file passed as argv[2]
const pairs = JSON.parse(fs.readFileSync(process.argv[2],'utf8'));
const lines = [];
for (const p of pairs) {
  const a = p.a, b = p.b, label = p.label || '';
  let out='', exit=0;
  try {
    out = execFileSync(EXE, ['--a', a, '--b', b], {encoding:'utf8', stdio:['ignore','pipe','pipe']});
  } catch (e) {
    out = (e.stdout||'');
    exit = (e.status===null||e.status===undefined)?-1:e.status;
    if (process.env.SHOWERR) process.stderr.write('ERR['+label+']: '+String(e.stderr||'').slice(-400)+'\n');
  }
  lines.push(JSON.stringify({a,b,out,exit}));
  console.log(label + ' || ' + JSON.stringify(out) + ' exit=' + exit);
}
fs.appendFileSync(OUT, lines.join('\n')+'\n');
console.error('appended ' + lines.length);

