const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const FILE = '/workspace/probes/draft201909-202012.jsonl';
const lines = fs.readFileSync(FILE,'utf8').split('\n').filter(x=>x.trim());
const N = lines.length;
const idxs = [];
const seed = 12345;
let s = seed;
function rnd(){ s = (s*1103515245+12345) & 0x7fffffff; return s/0x7fffffff; }
while(idxs.length<10){ const i = Math.floor(rnd()*N); if(!idxs.includes(i)) idxs.push(i); }
let bad=0;
for(const i of idxs){
  const rec = JSON.parse(lines[i]);
  let out='', exit=0;
  try { out = execFileSync(EXE,['--a',rec.a,'--b',rec.b],{encoding:'utf8',stdio:['ignore','pipe','pipe']}); }
  catch(e){ out=(e.stdout||''); exit=(e.status==null)?-1:e.status; }
  const ok = out===rec.out && exit===rec.exit;
  if(!ok) bad++;
  console.log((ok?'OK  ':'MISMATCH ')+'line'+(i+1)+' b='+rec.b.slice(0,90));
  if(!ok) console.log('   recorded='+JSON.stringify(rec.out)+' exit='+rec.exit+'\n   actual  ='+JSON.stringify(out)+' exit='+exit);
}
console.log('bad='+bad+' of '+idxs.length+'  totalLines='+N);
EOF
